{
  "name": "扫描器通信接口",
  "name_en": "Scanner Communication Interface",
  "manufacturer": "",
  "description": "用于实验系统中的非物理扫描器通信组件，提供向扫描器发送命令以及暴露文件描述符的能力，便于将设备通信接入事件循环、轮询或底层 I/O 监控流程。",
  "description_en": "A non-physical scanner communication component used in laboratory systems. It provides methods to send commands to a scanner and expose a file descriptor, enabling integration with event loops, polling, or low-level I/O monitoring.",
  "actions": [
    {
      "action_name": "auto-fileno",
      "description": "获取该扫描器通信接口对应的文件描述符。",
      "description_en": "Get the file descriptor associated with this scanner communication interface."
    },
    {
      "action_name": "auto-send_command",
      "description": "向扫描器发送命令，并可选择等待返回响应。",
      "description_en": "Send a command to the scanner and optionally wait for a reply."
    }
  ],
  "tag_hints": [
    "scanner communication",
    "command interface",
    "file descriptor I/O",
    "event loop integration",
    "instrument messaging"
  ]
}

